def classify_clean_exit_wrong(clean_exit: bool, ledger_unmet, reward_zero):
    """gh-1652 C4: the CLEAN-WRONG verdict for one trial.

    True = the trial exited on its own (no cap kill), its FINAL task
    ledger carries ZERO unmet items (the agent believed it was done),
    and the verifier still scored reward 0 — the agent validated through
    its own checklist, not the grader's oracle. False = not in the class
